from itertools import permutations
from functools import lru_cache
from sympy import Matrix
from sympy.matrices.normalforms import smith_normal_form
from sympy.polys.domains import ZZ

# Partitions in q^r, represented without trailing zeroes.
def parts_box(q, r, cap=None):
    if cap is None: cap = q
    out = []
    def rec(prev, left, a):
        if left == 0:
            while a and a[-1] == 0: a.pop()
            out.append(tuple(a)); return
        for x in range(min(prev, q), -1, -1):
            rec(x, left-1, a+[x])
    rec(cap, r, [])
    return sorted(set(out), key=lambda x:(sum(x), x))

def row(p, k): return p[k] if k < len(p) else 0
def size(p): return sum(p)
def contains(big, small):
    return all(row(big,k) >= row(small,k) for k in range(max(len(big),len(small))))
def invsign(p):
    return -1 if sum(p[a] > p[b] for a in range(len(p)) for b in range(a+1,len(p))) % 2 else 1

# First implementation: LR tableaux. Cells are visited top-to-bottom,
# and in each row from right to left, exactly as required.
@lru_cache(None)
def lr_tableau(lam, mu, nu):
    if not contains(nu, mu) or size(lam)+size(mu) != size(nu): return 0
    L = len(lam)
    if L == 0: return int(mu == nu)
    cells = []
    for rr in range(len(nu)):
        for cc in range(row(nu,rr), row(mu,rr), -1):
            cells.append((rr,cc))
    used = [0]*(L+1); filled = {}
    ans = 0
    def dfs(t):
        nonlocal ans
        if t == len(cells):
            ans += 1; return
        rr, cc = cells[t]
        right = filled.get((rr,cc+1))
        above = filled.get((rr-1,cc))
        for x in range(1,L+1):
            if used[x] == lam[x-1]: continue
            # weakly increasing along rows (left <= right), strictly down columns
            if right is not None and x > right: continue
            if above is not None and x <= above: continue
            # lattice condition for every right-to-left word prefix
            if x > 1 and used[x] + 1 > used[x-1]: continue
            used[x] += 1; filled[(rr,cc)] = x
            dfs(t+1)
            del filled[(rr,cc)]; used[x] -= 1
    dfs(0)
    return ans

# Second implementation: Jacobi--Trudi determinant, with each h_k
# multiplication independently expanded by Pieri horizontal strips.
def horizontal_strip(cur, nxt, q):
    if not contains(nxt, cur): return False
    for c in range(1,q+1):
        if sum(x >= c for x in nxt) - sum(x >= c for x in cur) > 1: return False
    return True

def make_pieri(box, q):
    bysize = {}
    for p in box: bysize.setdefault(size(p), []).append(p)
    @lru_cache(None)
    def hmult(k, mu):
        if k < 0: return ()
        if k == 0: return ((mu,1),)
        return tuple((nu,1) for nu in bysize.get(size(mu)+k,()) if horizontal_strip(mu,nu,q))
    return hmult

def lr_pieri(lam, mu, box, q):
    L = len(lam)
    if L == 0: return {mu:1}
    hmult = make_pieri(tuple(box), q)
    total = {}
    for p in permutations(range(L)):
        ks = [lam[a]-a+p[a] for a in range(L)]
        if any(k < 0 for k in ks): continue
        states = {mu:1}
        for k in ks:
            nxt = {}
            for cur,coef in states.items():
                for z,m in hmult(k,cur): nxt[z] = nxt.get(z,0) + coef*m
            states = nxt
        sg = invsign(p)
        for z,coef in states.items(): total[z] = total.get(z,0) + sg*coef
    return {z:c for z,c in total.items() if c}

# Required regressions, checked by tableau implementation and Pieri implementation
# in a box containing the indicated shapes.
regressions = [(((1,1),(1),(3)),0), (((1,1),(2),(2,2)),0)]
for (lam,mu,nu), expected in regressions:
    q, r = max(nu), len(nu)
    box = parts_box(q,r)
    a = lr_tableau(lam,mu,nu)
    b = lr_pieri(lam,mu,box,q).get(nu,0)
    assert a == expected and b == expected, (lam,mu,nu,a,b,expected)

records=[]
for r in range(2,4):
  for q in range(2,5):
    box = parts_box(q,r)
    nonempty = [x for x in box if x]
    for i in range(1,q):
      for j in range(1,r):
        rho = (i,)*j
        U = [x for x in box if contains(x,rho)]
        rows1=[]; rows2=[]
        for lam in nonempty:
          for mu in U:
            p = lr_pieri(lam,mu,box,q)
            v1=[]; v2=[]
            for nu in U:
              x = lr_tableau(lam,mu,nu)
              y = p.get(nu,0)
              assert x == y, ('LR disagreement',r,q,i,j,lam,mu,nu,x,y)
              v1.append(x); v2.append(y)
            rows1.append(v1); rows2.append(v2)
        assert rows1 == rows2
        D1 = smith_normal_form(Matrix(rows1), domain=ZZ)
        D2 = smith_normal_form(Matrix(rows2), domain=ZZ)
        assert D1 == D2
        diag=[abs(int(D1[k,k])) for k in range(min(D1.rows,D1.cols)) if D1[k,k] != 0]
        rank=len(diag); tors=[d for d in diag if d > 1]
        a=min(q-i,r-j); b=min(i,j)
        N=__import__('math').comb(a+b,a)
        records.append((r,q,i,j,len(U)-rank,tors,N))
        assert len(U)-rank == N and not tors, ('unexpected SNF',records[-1])

print('REGRESSIONS: c_(1,1),(1)^(3)=0; c_(1,1),(2)^(2,2)=0')
print('RANGE: 2<=r<=3, 2<=q=n-r<=4, 1<=i<q, 1<=j<r')
print('FORMAT r q i j | free_rank torsion | binomial(a+b,a)')
for x in records: print(*x[:4], '|', x[4], x[5], '|', x[6])
print('CASES',len(records),'ALL_TABLEAU_VS_PIERI_AND_SNF_COMPARISONS_PASSED')
